async delete(messageIds, deletePermanentlyOrOptions) {
  const options =
    typeof deletePermanentlyOrOptions == "boolean"
      ? { deletePermanently: deletePermanentlyOrOptions }
      : deletePermanentlyOrOptions;
  const deletePermanently = options?.deletePermanently ?? false;
  const isUserAction = options?.isUserAction ?? false;

"name": "options",
"optional": true,
"choices": [
  {
    "type": "boolean",
    "deprecated": "Specify the options object instead of a plain boolean to delete messages permanently.",
    "description": "Whether the message will be deleted permanently, regardless of the account's deletion behavior settings."
  },
  {
    "type": "object",
    "properties": {
      "deletePermanently": {
        "type": "boolean",
        "optional": true,
        "description": "Whether the message will be deleted permanently, regardless of the account's deletion behavior settings. A permanently deleted message cannot be restored, even if the action is defined as a user action. Use this with care!"
      },
      "isUserAction": {
        "type": "boolean",
        "optional": true,
        "description": "Whether this copy operation should be treated as a user action, for example allowing undo."
      }
    }
